const soortVoorop = s => ({ naam: 'Soort oorzaak voorop', woorden: { religieus: ['religieu'], economisch: ['economisch'], politiek: ['politiek'], sociaal: ['sociaal', 'sociale'] }[s], eerst: true, tip: `Begin met de soort: “Een ${SRT[s].bijv} oorzaak is ...”.`, mis: 'F3' });
const crit = (naam, woorden, tip, extra = {}) => ({ naam, woorden, tip, ...extra });

