const ton = (x, y) => `<ellipse cx="${x}" cy="${y}" rx="7" ry="9" fill="#9A6A3E" stroke="#5A3A1E"/><path d="M${x - 7} ${y - 3} H${x + 7} M${x - 7} ${y + 3} H${x + 7}" stroke="#5A3A1E"/>`;
